  //   Product(x, (x, 2, N)).has_reversed_limits
  //   => None
  it.todo("Product(x, (x, 2, N)).has_reversed_limits");
  it("Product(x, (x, 2, N)).subs(N, N + 2).has_reversed_limits", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("Integral(x**i, (i, 1, 3)).limits", () => {
    const i = new Sym('i');
    expect(sympyStr([[i, Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n })]], 'tt')).toBe('((i, 1, 3),)');
  });
